class Database
{
    private static ?PDO $connection = null;

    public static function getConnection(): PDO
    {
        if (self::$connection) {
            return self::$connection;
        }

        $configPath = __DIR__ . '/../config/database.php';
        if (!file_exists($configPath)) {
            throw new RuntimeException("Database not configured");
        }
        $config = require $configPath;
        if (!is_array($config)) {
             throw new RuntimeException("Database config is invalid");
        }

        if (!empty($config['use_bundled'])) {
            require_once __DIR__ . '/BundledMaria.php';
            BundledMaria::ensureRunningIfConfigured();
            // Re-read config in case ensureRunning updated the port
            $config = require $configPath;
        }
        $dsn = sprintf(
            'mysql:host=%s;port=%d;dbname=%s;charset=%s',
            $config['host'],
            $config['port'],
            $config['database'],
            $config['charset']
        );

        try {
            self::$connection = new PDO($dsn, $config['username'], $config['password'], self::pdoOptions($config));
        } catch (\PDOException $e) {
            if (!empty($config['use_bundled']) && class_exists('BundledMaria') && ($startupErr = BundledMaria::lastStartupError())) {
                throw new \RuntimeException("Built-in MariaDB failed to start:\n" . $startupErr, 0, $e);
            }

