    /**
     * Base PDO options + optional TLS. When the config has `use_tls => true`
     * we open an encrypted connection (without verifying the server cert,
     * which suits local / self-signed setups). This is the on/off the setup
     * screen exposes: leave it OFF for ordinary local MySQL / MariaDB; turn it
     * ON only if the server enforces secure transport. The bundled portable
     * MariaDB always runs with TLS off (loopback only).
     */
    public static function pdoOptions(array $config): array
    {
        $options = [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES => true,
            PDO::MYSQL_ATTR_LOCAL_INFILE => false,
            PDO::MYSQL_ATTR_MULTI_STATEMENTS => false,
            PDO::MYSQL_ATTR_INIT_COMMAND => "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci'",
        ];
        if (!empty($config['use_tls'])) {
            // Setting this attribute is what makes mysqlnd negotiate TLS; false
            // means "encrypt but don't verify the cert".
            $options[PDO::MYSQL_ATTR_SSL_VERIFY_SERVER_CERT] = false;
        }
        return $options;
    }

    // After an external client DROPs+CREATEs the active database (e.g. a backup
    // restore), the cached PDO's USE binding is dead. Clearing the singleton
    // forces the next getConnection() call to open a fresh connection.
    public static function reset(): void
    {
        self::$connection = null;
